const params=new URLSearchParams(location.search),names={昆明:'昆明',陇川:'陇川（瑞丽）',兰坪:'兰坪',凤庆:'凤庆'},from=params.get('from')||'昆明',to=params.get('to')||'陇川';const $=selector=>document.querySelector(selector);
$('#route').textContent=`${names[from]||from} → ${names[to]||to}`;$('#flight-summary').textContent=`${params.get('flight')||'JH1203'} · 运-12F · ${params.get('date')||''}`;const fare=Number(params.get('price'))||299,baggage=Number(params.get('baggageExtra'))||0,seatPrice=Number(params.get('seatPrice'))||0,seat=params.get('seat')||'';$('#fare-name').textContent=params.get('fare')||'基础经济舱';$('#fare-price').textContent=fare;$('#extras-price').textContent=baggage+seatPrice;$('#extras-name').textContent=[baggage?`行李 ¥${baggage}`:'',seat?`座位 ${seat}`:''].filter(Boolean).join(' · ')||'未添加';$('#total-price').textContent=Number(params.get('total'))||fare+baggage+seatPrice;
function fillMember(){let member=null;try{member=JSON.parse(localStorage.getItem('yunxiang-member')||'null')}catch{}if(!member){$('.form-error').textContent='当前浏览器中没有已注册的耀天会员资料。';return}const values={'#title':member.title,'#surname':member.surname,'#given-name':member.givenName,'#birthdate':member.birthdate,'#email':member.email,'#phone':member.phone,'#country-code':member.countryCode};Object.entries(values).forEach(([selector,value])=>{if(value&&$(selector))$(selector).value=value});$('#program').value='耀天会员';$('#member-number').value=member.username||'';$('.form-error').textContent='已填入当前浏览器保存的会员资料。'}$('#member-fill').addEventListener('click',fillMember);
const expiry=$('#document-expiry'),permanent=$('#permanent-document');expiry.min=new Date().toISOString().slice(0,10);permanent.addEventListener('change',()=>{expiry.disabled=permanent.checked;expiry.required=!permanent.checked;if(permanent.checked){expiry.value='';expiry.classList.remove('invalid');expiry.closest('label').querySelector('small').textContent='长期有效'}});
const form=$('#passenger-form');function validate(){let valid=true;form.querySelectorAll('[required]').forEach(input=>{const message=input.value.trim()?'':'请填写此项';input.classList.toggle('invalid',Boolean(message));input.closest('label')?.querySelector('small')&&(input.closest('label').querySelector('small').textContent=message);if(message)valid=false});const email=$('#email');if(email.value&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.value)){email.classList.add('invalid');email.closest('label').querySelector('small').textContent='请输入有效邮箱';valid=false}return valid}form.querySelectorAll('input,select').forEach(input=>input.addEventListener('input',()=>{input.classList.remove('invalid');const small=input.closest('label')?.querySelector('small');if(small)small.textContent=''}));form.addEventListener('submit',event=>{event.preventDefault();if(!validate()){form.querySelector('.invalid')?.focus();return}const passenger={title:$('#title').value,surname:$('#surname').value.trim(),givenName:$('#given-name').value.trim(),birthdate:$('#birthdate').value,email:$('#email').value.trim(),countryCode:$('#country-code').value,phone:$('#phone').value.trim(),program:$('#program').value,memberNumber:$('#member-number').value.trim()};try{sessionStorage.setItem('yunxiang-passenger',JSON.stringify(passenger))}catch{}const next=new URLSearchParams(params);location.href=`review.html?${next}`});
